def f(inputs: List[Tuple[int, str]]):
    def solve(e: str):
        stack = []
        num = ''
        for ch in e:
            if ch.isdigit():
                num += ch
            else:
                if num:
                    stack.append(int(num))
                    num = ''
                if ch in '+-*/(':
                    if ch == '(':
                        stack.append(ch)
                    elif ch == ')':
                        while stack[-1]!= '(':
                            a = stack.pop()
                            b = stack.pop()
                            stack.append(b + a)
                        stack.pop() # remove '('
                    else:
                        while stack and stack[-1] in '+-*/':
                            a = stack.pop()
                            b = stack.pop()
                            stack.append(b + a)
                        stack.append(ch)
                elif ch == '\0':
                    stack.append(int(num))
                    break
        return stack[0]

    results = []
    for n, e in inputs:
        results.append(solve(e))
    return results
